fn largest_divisor(n: i8) -> i8 {
    // Problem guarantees n > 1, and i8 max is 127.
    let nn: u16 = n as u16;

    // Find the smallest factor p >= 2. Then largest proper divisor is nn / p.
    let mut p: u16 = 0;
    let mut i: u16 = 2;

    while i * i <= nn {
        if nn % i == 0 {
            p = i;
            break;
        }
        i += 1;
    }

    let ans: u16 = if p != 0 { nn / p } else { 1 };
    ans as i8
}